import React, { useState } from 'react';
// تصحيح الاستيراد: التأكد من كتابة أسماء الأيقونات بشكل صحيح
import { User, Save,  FileText, Plus } from 'lucide-react';

const ProfilePage = () => {
  // استخدام State لجعل الحقول ديناميكية (ليست const)
  const [profileData, setProfileData] = useState({
    fullName: '',
    bio: '',
    github: '',
    portfolio: '',
    skills: ['ReactJS', 'Tailwind CSS']
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfileData({
      ...profileData,
      [name]: value
    });
  };

  const handleSave = () => {
    console.log("Saving data:", profileData);
    alert("Profile updated successfully!");
  };

  const styles = {
    container: { backgroundColor: '#fdfbff', minHeight: '100vh', padding: '40px 20px' },
    card: { backgroundColor: 'white', maxWidth: '850px', margin: '0 auto', borderRadius: '15px', boxShadow: '0 10px 25px rgba(0,0,0,0.05)', overflow: 'hidden' },
    header: { backgroundColor: '#c5a3d1', height: '120px' },
    content: { padding: '30px', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '30px' },
    inputGroup: { marginBottom: '20px' },
    label: { display: 'block', fontSize: '14px', fontWeight: 'bold', color: '#555', marginBottom: '8px', textAlign: 'left' },
    input: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd', fontSize: '14px' },
    btn: { backgroundColor: '#4a3f6b', color: 'white', padding: '12px 25px', borderRadius: '10px', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '10px', margin: '20px auto' }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <div style={styles.header}></div>
        
        <div style={{ padding: '0 30px', marginTop: '-50px', textAlign: 'left' }}>
          <div style={{ width: '100px', height: '100px', borderRadius: '50%', backgroundColor: '#eee', border: '4px solid white', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <User size={50} color="#ccc" />
          </div>
          <h2 style={{ color: '#4a3f6b' }}>{profileData.fullName || "Your Name"}</h2>
        </div>

        <div style={styles.content}>
          {/* Section 1 */}
          <div style={{ textAlign: 'left' }}>
            <h3 style={{ color: '#4a3f6b', borderBottom: '2px solid #f3e8ff' }}>Personal Info</h3>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Full Name</label>
              <input 
                name="fullName" 
                value={profileData.fullName} 
                onChange={handleChange} 
                style={styles.input} 
                placeholder="Ex: Ayoub" 
              />
            </div>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Bio</label>
              <textarea 
                name="bio" 
                value={profileData.bio} 
                onChange={handleChange} 
                style={{ ...styles.input, height: '80px' }} 
                placeholder="Tell us about yourself" 
              />
            </div>
          </div>

          {/* Section 2 */}
          <div style={{ textAlign: 'left' }}>
            <h3 style={{ color: '#4a3f6b', borderBottom: '2px solid #f3e8ff' }}>Links</h3>
            <div style={styles.inputGroup}>
              <label style={styles.label}>GitHub URL</label>
              <input 
                name="github" 
                value={profileData.github} 
                onChange={handleChange} 
                style={styles.input} 
                placeholder="https://github.com/..." 
              />
            </div>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Portfolio</label>
              <input 
                name="portfolio" 
                value={profileData.portfolio} 
                onChange={handleChange} 
                style={styles.input} 
                placeholder="https://..." 
              />
            </div>
          </div>
        </div>

        <button style={styles.btn} onClick={handleSave}>
          <Save size={18} /> Save Digital CV
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
